"use client";

import { useId, useState, type ChangeEvent, type FormEvent } from "react";
import { useMutation, useQuery } from "convex/react";
import { LoaderCircleIcon, PencilIcon, PlusIcon } from "lucide-react";

import { api } from "@/convex/_generated/api";
import type { Id } from "@/convex/_generated/dataModel";
import { Button } from "@/components/ui/button";
import {
  Dialog,
  DialogClose,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import {
  Field,
  FieldError,
  FieldGroup,
  FieldLabel,
  FieldTitle,
} from "@/components/ui/field";
import { Input } from "@/components/ui/input";

import { ALL } from "../util/functions";
import { useWorkspace } from "@/components/workspace";

type FormValues = {
  itemName: string;
  sku: string;
  category: string;
  supplierName: string;
  customerName: string;
  quantity: string;
  quantityUnit: string;
  unitPrice: string;
};

type FieldErrors = Partial<Record<keyof FormValues, string>>;

const EMPTY_FORM: FormValues = {
  itemName: "",
  sku: "",
  category: "",
  supplierName: "",
  customerName: "",
  quantity: "",
  quantityUnit: "",
  unitPrice: "",
};

/** The line-item fields the dialog needs when editing an existing row. */
export type EditableItem = {
  id: Id<"lineItems">;
  itemName: string;
  sku: string;
  category: string;
  supplierName: string;
  customerName: string;
  quantity: number | null;
  quantityUnit: string | null;
  unitPrice: number | null;
};

/** Turn a table row into form values, treating the table's dash as empty. */
function formFromItem(item: EditableItem): FormValues {
  const text = (value: string) => (value === "—" ? "" : value);

  return {
    itemName: text(item.itemName),
    sku: item.sku,
    category: text(item.category),
    supplierName: text(item.supplierName),
    customerName: text(item.customerName),
    quantity: item.quantity === null ? "" : String(item.quantity),
    quantityUnit: item.quantityUnit ?? "",
    unitPrice: item.unitPrice === null ? "" : String(item.unitPrice),
  };
}

/** Pull the readable part out of Convex's wrapped server error. */
function describeError(error: unknown) {
  const message = error instanceof Error ? error.message : String(error);
  const serverError = message.split("Server Error").pop()?.trim();

  return (
    serverError?.replace(/^Uncaught Error:\s*/i, "") ||
    "Couldn't save the item. Please try again."
  );
}

interface AddItemDialogProps {
  open?: boolean;
  onOpenChange?: (open: boolean) => void;
  /** Pass a line item to switch the dialog into edit mode. */
  item?: EditableItem | null;
}

/**
 * Add or edit one line item. Mount the form only while the dialog is open so
 * each opening starts from the current row (or a blank add form).
 */
export function AddItemDialog({
  open: externalOpen,
  onOpenChange: externalOnOpenChange,
  item = null,
}: AddItemDialogProps) {
  const [internalOpen, setInternalOpen] = useState(false);

  const isOpen = externalOpen ?? internalOpen;
  const setIsOpen = externalOnOpenChange ?? setInternalOpen;

  return (
    <Dialog open={isOpen} onOpenChange={setIsOpen}>
      <DialogContent className="max-h-[calc(100svh-2rem)] overflow-y-auto sm:max-w-lg">
        <AddItemForm
          key={isOpen ? (item?.id ?? "new") : "closed"}
          item={item}
          onSaved={() => setIsOpen(false)}
        />
      </DialogContent>
    </Dialog>
  );
}

function AddItemForm({
  item,
  onSaved,
}: {
  item: EditableItem | null;
  onSaved: () => void;
}) {
  const { workspace } = useWorkspace();
  const idPrefix = useId();
  const ids = {
    name: `${idPrefix}-name`,
    sku: `${idPrefix}-sku`,
    category: `${idPrefix}-category`,
    categories: `${idPrefix}-categories`,
    supplier: `${idPrefix}-supplier`,
    suppliers: `${idPrefix}-suppliers`,
    customer: `${idPrefix}-customer`,
    customers: `${idPrefix}-customers`,
    quantity: `${idPrefix}-quantity`,
    unit: `${idPrefix}-unit`,
    price: `${idPrefix}-price`,
  };

  const [form, setForm] = useState<FormValues>(() =>
    item
      ? formFromItem(item)
      : {
          ...EMPTY_FORM,
          customerName: workspace === ALL ? "" : workspace,
        },
  );
  const [errors, setErrors] = useState<FieldErrors>({});
  const [formError, setFormError] = useState<string | null>(null);
  const [pending, setPending] = useState(false);

  const isEditing = item !== null;

  const options = useQuery(api.inventory.helpers.getItemFormOptions);
  const ensureSupplier = useMutation(api.inventory.helpers.ensureSupplier);
  const ensureCustomer = useMutation(api.inventory.helpers.ensureCustomer);
  const addItem = useMutation(api.inventory.item.addItem);
  const updateItem = useMutation(api.inventory.item.updateItem);

  const quantity = Number(form.quantity);
  const unitPrice = Number(form.unitPrice);
  const hasNumbers =
    form.quantity.trim() !== "" &&
    form.unitPrice.trim() !== "" &&
    Number.isFinite(quantity) &&
    Number.isFinite(unitPrice);
  const total = hasNumbers ? Math.round(quantity * unitPrice * 100) / 100 : 0;

  const update =
    (field: keyof FormValues) => (event: ChangeEvent<HTMLInputElement>) => {
      const { value } = event.target;
      setForm((current) => ({ ...current, [field]: value }));

      // Clear this field's error as soon as the user edits it.
      setErrors((current) => {
        if (!current[field]) return current;
        const next = { ...current };
        delete next[field];
        return next;
      });
    };

  const handleSubmit = async (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    if (pending) return;

    const values = {
      itemName: form.itemName.trim(),
      sku: form.sku.trim(),
      category: form.category.trim(),
      supplierName: form.supplierName.trim(),
      customerName: form.customerName.trim(),
      quantityUnit: form.quantityUnit.trim(),
    };

    const nextErrors: FieldErrors = {};
    if (!values.itemName) nextErrors.itemName = "Enter the item name.";
    if (!values.category) nextErrors.category = "Enter a category.";
    if (!values.supplierName) nextErrors.supplierName = "Enter a supplier.";
    if (!values.customerName) nextErrors.customerName = "Enter a customer.";
    if (!values.quantityUnit)
      nextErrors.quantityUnit = "Enter a unit, e.g. kg.";
    if (
      form.quantity.trim() === "" ||
      !Number.isFinite(quantity) ||
      (isEditing ? quantity < 0 : quantity <= 0)
    ) {
      nextErrors.quantity = isEditing
        ? "Enter a quantity of 0 or more."
        : "Enter a quantity above 0.";
    }
    if (
      form.unitPrice.trim() === "" ||
      !Number.isFinite(unitPrice) ||
      unitPrice < 0
    ) {
      nextErrors.unitPrice = "Enter a price of 0 or more.";
    }

    setErrors(nextErrors);
    if (Object.keys(nextErrors).length > 0) return;

    setPending(true);
    setFormError(null);

    try {
      // Both mutations need existing supplier/customer rows, so resolve both
      // names (creating them on first use) before writing the line item.
      const [supplierId, customerId] = await Promise.all([
        ensureSupplier({ supplierName: values.supplierName }),
        ensureCustomer({ customerName: values.customerName }),
      ]);

      if (item) {
        await updateItem({
          itemId: item.id,
          customerId,
          supplierId,
          sku: values.sku || null,
          itemName: values.itemName,
          category: values.category,
          quantity,
          quantityUnit: values.quantityUnit,
          unitPrice,
        });
      } else {
        await addItem({
          sku: values.sku || null,
          itemName: values.itemName,
          category: values.category,
          quantity,
          quantityUnit: values.quantityUnit,
          unitPrice,
          total,
          supplierId,
          customerId,
          searchField: values.itemName.toLowerCase(),
        });
      }

      onSaved();
    } catch (error) {
      setFormError(describeError(error));
    } finally {
      setPending(false);
    }
  };

  return (
    <>
      <DialogHeader>
        <DialogTitle>{isEditing ? "Edit item" : "Add item"}</DialogTitle>
        <DialogDescription>
          {isEditing
            ? "Update this line item. Changing the item name, category, or supplier also updates the shared item record."
            : "Record a purchase by hand. Suppliers and customers that aren’t in the list yet are created when you save."}
        </DialogDescription>
      </DialogHeader>

      <form onSubmit={handleSubmit} noValidate className="flex flex-col gap-4">
        <FieldGroup className="gap-4">
          <Field data-invalid={Boolean(errors.itemName)}>
            <FieldLabel htmlFor={ids.name}>Item name</FieldLabel>
            <Input
              id={ids.name}
              value={form.itemName}
              onChange={update("itemName")}
              placeholder="Norwegian salmon filet"
              aria-invalid={Boolean(errors.itemName)}
              autoComplete="off"
            />
            {errors.itemName && <FieldError>{errors.itemName}</FieldError>}
          </Field>

          <div className="grid gap-4 sm:grid-cols-2">
            <Field>
              <FieldLabel htmlFor={ids.sku}>SKU (optional)</FieldLabel>
              <Input
                id={ids.sku}
                value={form.sku}
                onChange={update("sku")}
                placeholder="e.g. 4011"
                autoComplete="off"
              />
            </Field>

            <Field data-invalid={Boolean(errors.category)}>
              <FieldLabel htmlFor={ids.category}>Category</FieldLabel>
              <Input
                id={ids.category}
                list={ids.categories}
                value={form.category}
                onChange={update("category")}
                placeholder="Fish"
                aria-invalid={Boolean(errors.category)}
                autoComplete="off"
              />
              {errors.category && <FieldError>{errors.category}</FieldError>}
            </Field>
          </div>

          <div className="grid gap-4 sm:grid-cols-2">
            <Field data-invalid={Boolean(errors.supplierName)}>
              <FieldLabel htmlFor={ids.supplier}>Supplier</FieldLabel>
              <Input
                id={ids.supplier}
                list={ids.suppliers}
                value={form.supplierName}
                onChange={update("supplierName")}
                placeholder="BAMA Storkjøkken Oslo"
                aria-invalid={Boolean(errors.supplierName)}
                autoComplete="off"
              />
              {errors.supplierName && (
                <FieldError>{errors.supplierName}</FieldError>
              )}
            </Field>

            <Field data-invalid={Boolean(errors.customerName)}>
              <FieldLabel htmlFor={ids.customer}>Customer</FieldLabel>
              <Input
                id={ids.customer}
                list={ids.customers}
                value={form.customerName}
                onChange={update("customerName")}
                placeholder="Osteria De Campo"
                aria-invalid={Boolean(errors.customerName)}
                autoComplete="off"
              />
              {errors.customerName && (
                <FieldError>{errors.customerName}</FieldError>
              )}
            </Field>
          </div>

          <div className="grid gap-4 sm:grid-cols-2">
            <Field data-invalid={Boolean(errors.quantity)}>
              <FieldLabel htmlFor={ids.quantity}>Quantity</FieldLabel>
              <Input
                id={ids.quantity}
                type="number"
                inputMode="decimal"
                min="0"
                step="any"
                value={form.quantity}
                onChange={update("quantity")}
                placeholder="1"
                aria-invalid={Boolean(errors.quantity)}
              />
              {errors.quantity && <FieldError>{errors.quantity}</FieldError>}
            </Field>

            <Field data-invalid={Boolean(errors.quantityUnit)}>
              <FieldLabel htmlFor={ids.unit}>Unit</FieldLabel>
              <Input
                id={ids.unit}
                value={form.quantityUnit}
                onChange={update("quantityUnit")}
                placeholder="kg"
                aria-invalid={Boolean(errors.quantityUnit)}
                autoComplete="off"
              />
              {errors.quantityUnit && (
                <FieldError>{errors.quantityUnit}</FieldError>
              )}
            </Field>
          </div>

          <div className="grid gap-4 sm:grid-cols-2">
            <Field data-invalid={Boolean(errors.unitPrice)}>
              <FieldLabel htmlFor={ids.price}>Unit price (kr)</FieldLabel>
              <Input
                id={ids.price}
                type="number"
                inputMode="decimal"
                min="0"
                step="0.01"
                value={form.unitPrice}
                onChange={update("unitPrice")}
                placeholder="48.00"
                aria-invalid={Boolean(errors.unitPrice)}
              />
              {errors.unitPrice && <FieldError>{errors.unitPrice}</FieldError>}
            </Field>

            <Field>
              <FieldTitle>Total</FieldTitle>
              <div
                aria-live="polite"
                className="flex h-8 items-center justify-between rounded-lg border border-input bg-muted/40 px-2.5 text-sm tabular-nums"
              >
                <span>{total.toFixed(2)}</span>
                <span className="text-xs text-muted-foreground">kr</span>
              </div>
            </Field>
          </div>
        </FieldGroup>

        {formError && (
          <p role="alert" className="text-sm text-destructive">
            {formError}
          </p>
        )}

        <DialogFooter>
          <DialogClose render={<Button type="button" variant="outline" />}>
            Cancel
          </DialogClose>
          <Button type="submit" disabled={pending}>
            {pending ? (
              <LoaderCircleIcon className="animate-spin" />
            ) : isEditing ? (
              <PencilIcon />
            ) : (
              <PlusIcon />
            )}
            {pending
              ? isEditing
                ? "Saving…"
                : "Adding…"
              : isEditing
                ? "Save changes"
                : "Add item"}
          </Button>
        </DialogFooter>
      </form>

      <datalist id={ids.categories}>
        {options?.categories.map((category) => (
          <option key={category} value={category} />
        ))}
      </datalist>
      <datalist id={ids.suppliers}>
        {options?.suppliers.map((supplier) => (
          <option key={supplier} value={supplier} />
        ))}
      </datalist>
      <datalist id={ids.customers}>
        {options?.customers.map((customer) => (
          <option key={customer} value={customer} />
        ))}
      </datalist>
    </>
  );
}
